entries[54860] = { ["name"] = "X-53 Reiserakete", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 60\nBenötigt Reiten (225)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine X-53 Reitrakete oder gibt sie frei. Die Geschwindigkeit dieser Transportmaschine für zwei Personen hängt von Eurer Reitfertigkeit ab." }
entries[56806] = { ["name"] = "Mini-Thor", ["text"] = "Accountgebunden\nBenutzen: Lehrt Euch, wie man einen winzigen Thor beschwört.\nMit Rechtsklick einen Mini-Thor aufstellen und freigeben." }
entries[122270] = { ["name"] = "WoW-Marke", ["text"] = "Wird beim Aufheben gebunden\n\"Kann gegen Gold im Auktionshaus verkauft werden. Der Gewinner der Auktion kann die Marke für 30 Tage Spielzeit einlösen.\"" }
entries[122284] = { ["name"] = "WoW-Marke", ["text"] = "Wird beim Aufheben gebunden\n\"Benutzen: Fügt Ihrem World of Warcraft-Account 30 Tage Spielzeit hinzu.\"" }
