entries[184871] = { ["name"] = "Dunkles Portal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt Euch zurück nach: <Hearthstone Location>. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\"UND SIEHE, DAS DUNKLE PORTAL. Na ja, zumindest eine kleine Version davon.\"" }
