entries[186683] = { ["name"] = "Formel: Ring - Werte", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst (375)\nBenötigt Die Wächter der Sande\n- Respektvoll\nBenutzen: Lehrt Euch, einen Ring dauerhaft so zu verzaubern, dass er alle Werte um 4 erhöht.\nEinen Ring dauerhaft verzaubern, sodass er alle Werte um 4 erhöht. Nur Ringe des Verzauberers können verzaubert werden und sind danach seelengebunden. Erfordert einen Gegenstand der Stufe 35 oder höher." }
entries[187048] = { ["name"] = "Muster: Große Trommeln der Wiederherstellung", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (350)\nBenötigt Kurenai\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Großen Trommeln der Wiederherstellung.\nGroße Trommeln der Wiederherstellung\nBenötigt Lederverarbeitung (350)\nBenutzen: Stellt im Verlauf von 15 sec 600 Gesundheit und Mana von Gruppenmitgliedern innerhalb von 40 Metern wieder her. Trommeln können in gestaltverändertem Zustand benutzt werden. Unwirksam bei Zielen der Stufe 80 oder höher. (2 Min Abklingzeit)\n50 AufladungenBenötigt Schweres Knotenhautleder (6), Netherdrachenschuppe (4)" }
entries[187049] = { ["name"] = "Muster: Große Trommeln des Tempos", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (345)\nBenötigt Kurenai\n- Wohlwollend\nBenutzen: Lehrt Euch die Herstellung von Großen Trommeln des Tempos.\nGroße Trommeln des Tempos\nBenötigt Lederverarbeitung (340)\nBenutzen: Erhöht das Bewegungstempo von Gruppenmitgliedern innerhalb von 40 Metern um 15%. Hält 30 sec lang an. Trommeln können in gestaltverändertem Zustand benutzt werden. (2 Min Abklingzeit)\n50 AufladungenBenötigt Schweres Knotenhautleder (6), Windschuppen (4)" }
