entries[211844] = { ["name"] = "Das Siegel des Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+50 Ausdauer\n+51 Intelligenz\nBenötigt Stufe 80\nAnlegen: Erhöht die Trefferwertung um 39.\nAnlegen: Erhöht die Tempowertung um 48.\nAnlegen: Erhöht die Zaubermacht um 78." }
entries[211847] = { ["name"] = "Band der bösen Hexe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+50 Ausdauer\n+51 Intelligenz\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 45.\nAnlegen: Stellt alle 5 Sek. 23 Mana wieder her.\nAnlegen: Erhöht die Zaubermacht um 78." }
entries[211850] = { ["name"] = "Der erschreckende Helm des Reiters", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n1925 Rüstung\n+120 Stärke\n+137 Ausdauer\n\nMetasockel\nGelber Sockel\nSockelbonus: +8 Stärke\n\nHaltbarkeit 100 / 100\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 63.\nAnlegen: Erhöht die Trefferwertung um 50.\nBenutzen: Lasst den kopflosen Reiter durch Eure Kehle lachen. (30 Sek. Abklingzeit)" }
entries[211851] = { ["name"] = "Die elende Klinge des Reiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWaffenhand Schwert\n338 - 628 Schaden Tempo 2.70\n(178.89 Schaden pro Sekunde)\n+35 Beweglichkeit\n+52 Ausdauer\nHaltbarkeit 105 / 105\nBenötigt Stufe 80\nAnlegen: Erhöht die Trefferwertung um 34.\nAnlegen: Erhöht die Angriffskraft um 102.\nAnlegen: Erhöht Eure Waffenkundewertung um 34.\nBenutzen: Beschwört Kürbissoldaten, um Eure Feinde zu verbrennen. (10 Min Abklingzeit)\n\"Steht auf, Soldaten... steht auf und kämpft!\"" }
